def solve(items):
    import re
    total_seconds = 0
    for item in items:
        days = re.search(r'(\d+)d', item)
        hours = re.search(r'(\d+)h', item)
        minutes = re.search(r'(\d+)m', item)
        seconds = re.search(r'(\d+)s', item)

        if days:
            total_seconds += int(days.group(1)) * 86400
        if hours:
            total_seconds += int(hours.group(1)) * 3600
        if minutes:
            total_seconds += int(minutes.group(1)) * 60
        if seconds:
            total_seconds += int(seconds.group(1))
    return total_seconds

