import re

def parse_duration(s):
    # s is like "1d 16h 25s"
    total_seconds = 0
    # Find all matches of number followed by unit (d, h, m, s)
    matches = re.findall(r'(\d+)([dhms])', s)
    for val_str, unit in matches:
        val = int(val_str)
        if unit == 'd':
            total_seconds += val * 24 * 3600
        elif unit == 'h':
            total_seconds += val * 3600
        elif unit == 'm':
            total_seconds += val * 60
        elif unit == 's':
            total_seconds += val
    return total_seconds

def solve(s):
    return parse_duration(s)

